files.hooks/register.ts:
import type { EngineInterface, Register, ToolCallInput, ToolCallResult } from "claude-code";

import { type Found, type Host, needlesOf, scanChanges, scanTargets } from "./scan.ts";
import { filled, FIXES, restoreCommand, shellQuote } from "./shell.ts";
import {
  createVault,
  entered,
  isInert,
  mergeTyped,
  PLUGIN,
  VARIABLE_NAME,
  walkStrings,
} from "./vault.ts";

export const TOOL = `mcp__${PLUGIN}__request_secret`;

export const PANE = PLUGIN;

export const FIELD = "secret";

const DOT = "•";

const WAIT_MS = 10 * 60_000;

/** A hook's own time is capped; a wait spent inside a host call is not counted, so the box is waited for in short sleeps. */
const POLL = ["sleep", "0.3"] as const;

/** Native Windows has no `sleep` executable; PowerShell's is the one every install carries. */
const POLL_WINDOWS = [
  "powershell",
  "-NoProfile",
  "-Command",
  "Start-Sleep -Milliseconds 300",
] as const;

const PANE_ROWS = 7;

/** What one `$.fs.read` takes: a larger file rejects. */
const READ_LIMIT = 4 * 1024 * 1024;

/** The tools whose stored record can hold a command's output or a file's text. */
type Reader = "Bash" | "Read" | "Write" | "Edit" | "NotebookEdit" | "Monitor" | "GetTask" | "LSP";

/** The tools that write the text the model gave them into a file, a placeholder as text. */
type FileWrite = Extract<ToolCallInput, { tool: "Write" | "Edit" | "NotebookEdit" }>;

const ANYWHERE =
  'Write the placeholder in a Bash command where the value goes, as you would write the value: curl -H "Authorization: Bearer <placeholder>" https://..., API_KEY=<placeholder> npm test.';

const WHOLE_WORD = [
  "Write the placeholder as a whole single-quoted word, '<placeholder>', in one Bash command or a pipe of two:",
  `${FIXES.secret}, ${FIXES.bearer};`,
  `to build a longer text with it, pipe it, as in ${FIXES.header}`,
].join(" ");

const DESCRIPTION = [
  "Asks the user for a secret (an API key, a token, a password) in a masked box beside the transcript, so the value never enters the conversation.",
  "Answers the variable name and a placeholder of the form [secret-pane:NAME:xxxxxxxx], which becomes the real value inside a Bash command; the value is hidden again in everything that comes back.",
  ANYWHERE,
  "A value holding characters the shell reads (a space, a quote, $...) goes in only as a whole single-quoted word, '<placeholder>', and the answer says which applies.",
  "A command is refused, with the reason and the fix, when it would put the value where it cannot be taken back (a git subcommand that writes history or sends it out, a gh command other than gh secret, a commit while a change holds the value) or runs in the background.",
  "No other tool restores a placeholder: Write and Edit refuse one. The value lives in this session's memory only: the mod writes nothing to disk, and a new session or /clear asks the user again.",
  "Use it in place of asking the user to paste a secret into the chat.",
].join(" ");

const WITHHELD = `${PLUGIN}: could not check this result for a kept value, so the result was withheld. Narrow the call (head, grep, offset) and retry.`;

const NOT_RUN = `${PLUGIN}: could not check this command against the kept values, so it was not run.`;

const BLOCK_WITHHELD = `[${PLUGIN} withheld this text: the check for a kept value failed]`;

const WRITE_UNCHECKED = `${PLUGIN}: could not check this text for a placeholder of this session, so the file was not written.`;

const RUN = "Run it";

const SKIP = "Don't run it";

type Pending = {
  readonly name: string;
  readonly reason: string;
  value: string;
  error: string | null;
  answer: string | undefined;
  isInBand: boolean;
};

let pending: Pending | null = null;

const vault = createVault();

/** Each command restored for a call in flight, mapped to the command as Claude wrote it. */
const asWritten = new Map<string, string>();

/* oxlint-disable anti-slop/no-unknown-parameters, anti-slop/no-runtime-typeof -- a tool argument is the model's own, `unknown` as the engine hands it; these reads ARE the boundary. */
function argument(value: unknown): string {
  return typeof value === "string" ? value.trim() : "";
}

/** The command a permission check reads for Bash, or nothing where the input is no Bash input. */
function shellCommand(input: unknown): string | null {
  if (typeof input !== "object" || input === null || !("command" in input)) return null;

  return typeof input.command === "string" ? input.command : null;
}
/* oxlint-enable anti-slop/no-unknown-parameters, anti-slop/no-runtime-typeof */

type ReadResult = ToolCallResult<Reader>;

type Answer = Exclude<ReadResult, { deny: string }>;

type Errored = Extract<ReadResult, { isError: true }>;

type Answered = Exclude<Answer, Errored>;

/** The tool's answer with every kept value hidden, and without `ref`: core would read its own messages verbatim with it. */
function hidden(ran: Answer, hide: (text: string) => string): ReadResult {
  if (ran.isError === true) {
    const errored: Errored = { isError: true, result: walkStrings(ran.result, hide) };

    if (ran.text !== undefined) errored.text = hide(ran.text);

    if (ran.context !== undefined) errored.context = ran.context.map(hide);

    return errored;
  }

  // SAFETY: `walkStrings` keeps a plain value's shape and rewrites its strings alone, and a tool's record is plain data.
  const result = walkStrings(ran.result, hide) as Answered["result"];
  const answered: Answered = { result };

  if (ran.context !== undefined) answered.context = ran.context.map(hide);

  return answered;
}

function fileText(e: FileWrite): string {
  if (e.tool === "Write") return e.content;

  return e.tool === "Edit" ? e.new_string : e.new_source;
}

function writeRefused(tag: string): string {
  return filled(
    [
      `${PLUGIN}: the file was not written: <placeholder> stands for a kept value, and this tool would write the placeholder as text.`,
      `To put the value in a file, write it from Bash: ${FIXES.file}.`,
      "To mention the secret without its value, write <NAME>.",
    ].join(" "),
    tag,
  );
}

function hostOf($: EngineInterface): Host {
  return {
    run: (argv, cwd) => $.process.run(argv, cwd === undefined ? {} : { cwd }),
    read: async (path) => {
      const stat = await $.fs.stat(path);

      return stat.kind === "file" && stat.size <= READ_LIMIT ? $.fs.read(path) : null;
    },
    exists: (path) => $.fs.exists(path),
  };
}

function fixOf({ path, where }: Found): string {
  if (where === "handed")
    return `${path} (read by the command: leave it out, or take the value out of it)`;

  return where === "tracked"
    ? `${path} (tracked: take the value out, or stop tracking it with git rm --cached ${shellQuote(path)} and add it to .gitignore)`
    : `${path} (untracked: add it to .gitignore)`;
}

/** Why a command that may commit or publish may not run while a change it could carry holds a kept value, or nothing. */
async function changesRefusal($: EngineInterface, command: string): Promise<string | undefined> {
  const targets = scanTargets(command, await $.env.get("HOME"));

  if (targets.length === 0) return undefined;
  const needles = needlesOf(vault.values());
  const host = hostOf($);

  for (const target of targets) {
    const checked = `\`${target.label}\` may commit or publish, so the changes it could carry are read for a kept value first`;

    if (target.kind === "unknown") {
      return `${PLUGIN}: the command was not run: ${checked}, and the mod cannot tell where \`${target.spelling}\` leads: write that directory or file as a path.`;
    }

    const scan = await scanChanges(host, target, needles);

    if (scan.kind === "found") {
      return `${PLUGIN}: the command was not run: \`${target.label}\` may commit or publish, and a kept value stands in ${scan.files.map(fixOf).join(", ")}. Then run it again.`;
    }

    if (scan.kind === "failed") {
      return `${PLUGIN}: the command was not run: ${checked}, and that check failed: ${scan.why}. Fix what it names and run it again; a /clear forgets the kept values, and the check with them.`;
    }
  }

  return undefined;
}

function answerText(name: string, tag: string, value: string): string {
  const kept = `The user entered ${name} (${value.length} characters). The value is kept in this session's memory; you can't see it. Its placeholder: ${tag}.`;

  if (isInert(value)) return `${kept} ${filled(ANYWHERE, tag)}`;

  return `${kept} The value holds characters the shell reads. ${filled(WHOLE_WORD, tag)}`;
}

type Drawn = Parameters<EngineInterface["ui"]["resolve"]>[0];

/** A surface that draws an `Input`: every one but mobile, whose table has none. */
type Typed = Drawn & { readonly surface: "terminal" | "desktop" | "vscode" };

function drawBox($: EngineInterface, e: Typed, p: Pending) {
  const { Box, Text, Input } = $.ui.resolve(e);
  const focusHint = p.isInBand ? "ctrl+x then tab to focus, Enter on empty cancels" : "Esc cancels";
  const count = p.value.length === 0 ? "" : `${p.value.length} characters · `;

  return Box({
    flexDirection: "column",
    paddingX: 1,
    children: [
      Text({ bold: true, children: `Claude is asking for ${p.name}` }),
      ...(p.reason === "" ? [] : [Text({ dimColor: true, children: p.reason })]),
      Input({
        key: FIELD,
        label: "value ",
        placeholder: "paste it here, it stays masked",
        value: DOT.repeat(p.value.length),
        submitLabel: "save",
        autoFocus: true,
        onInput: (drawn) => {
          const merged = mergeTyped(p.value, drawn, DOT);

          p.value = merged ?? "";
          p.error =
            merged === null
              ? "an edit in the middle of the field cannot be read: the field was emptied, paste the value again"
              : null;
          $.ui.invalidate("ui.render");
        },
        onSubmit: () => {
          if (p.isInBand && p.value.trim() === "") {
            p.answer = "";

            return;
          }

          const kept = entered(p.value);

          if (kept.kind === "kept") p.answer = kept.value;
          else p.error = kept.why;
          $.ui.invalidate("ui.render");
        },
      }),
      ...(p.error === null ? [] : [Text({ color: "yellow", children: p.error })]),
      Text({
        dimColor: true,
        children: `${count}Enter saves · ${focusHint} · Claude never sees the value`,
      }),
    ],
  });
}

/** Every text a row carries the model reads, with each kept value hidden; the row itself when none was. */
function hiddenContent<B extends { readonly type: string }>(
  content: readonly B[],
  hide: (text: string) => string,
): B[] {
  return content.map((block) => {
    if (block.type !== "text" && block.type !== "tool_result") return block;

    // SAFETY: a text block's and a tool_result's content are plain data, and walkStrings keeps their shape.
    return walkStrings(block, hide) as B;
  });
}

function forget(): void {
  vault.clear();
  asWritten.clear();
  pending = null;
}

export const register: Register = (on) => {
  on("session.start", async ($, e, next) => {
    forget();
    await $.tool.register({
      name: "request_secret",
      description: DESCRIPTION,
      inputSchema: {
        type: "object",
        properties: {
          name: {
            type: "string",
            description: "The variable name the secret is known by, such as PARENT_REPO_PAT",
          },
          reason: {
            type: "string",
            description: "One short line telling the user why it is needed",
          },
        },
        required: ["name", "reason"],
      },
      isDeferred: false,
    });

    return next(e);
  });

  // A /clear ends the conversation with no session.start after it: the values go with it.
  on("session.end", (_$, e, next) => {
    forget();

    return next(e);
  });

  on("tool.call", { tool: "mcp__secret-pane__request_secret" }, async ($, e, next) => {
    const name = argument(e.name);

    if (!VARIABLE_NAME.test(name)) {
      return {
        result: `"${name}" is not a variable name: letters, digits and underscores, not starting with a digit.`,
      };
    }

    if (!(await $.session.surfaces()).some((surface) => surface !== "mobile")) {
      return {
        result: `${PLUGIN} needs an interactive session with a terminal or a desktop to collect ${name}: nobody can type into the box here.`,
      };
    }

    if (pending !== null) {
      return {
        result: `${PLUGIN} is already waiting for ${pending.name}. Ask for one secret at a time.`,
      };
    }

    const request: Pending = {
      name,
      reason: argument(e.reason),
      value: "",
      error: null,
      answer: undefined,
      isInBand: false,
    };

    pending = request;

    try {
      const opened = await $.ui.open({
        id: PANE,
        title: PLUGIN,
        focus: true,
        closeOnEscape: true,
        holdToasts: true,
        rows: PANE_ROWS,
      });

      if (!opened.isPlaced) {
        request.isInBand = true;
        await $.ui.close({ id: PANE });
        $.ui.invalidate("ui.render");
        $.ui.toast(
          `Claude asks for ${name}: press ctrl+x then tab to type it in the box above the prompt`,
          { timeoutMs: 10_000 },
        );
      }

      const poll = (await $.env.get("OS")) === "Windows_NT" ? POLL_WINDOWS : POLL;
      const deadline = (await $.clock.now()) + WAIT_MS;

      while (
        request.answer === undefined &&
        !next.signal.aborted &&
        (await $.clock.now()) < deadline
      ) {
        await $.process.run(poll);
      }
    } finally {
      // Whatever ends the wait, an Escape of the call included (it skips the hook with no `.catch`), the slot and the box go.
      if (pending === request) pending = null;
      await $.ui.close({ id: PANE }).catch(() => {});
      $.ui.invalidate("ui.render");
    }

    const value = request.answer;

    if (value === undefined) {
      return { result: `${PLUGIN} waited for ${name} and nothing was entered. Nothing was kept.` };
    }

    if (value === "") return { result: `The user cancelled. ${name} was not kept.` };
    const tag = vault.tagOf(name, value, await $.clock.now());

    $.ui.toast(`${name} kept for this session`);

    return { result: answerText(name, tag, value) };
  }).catch(($, _e, next) => {
    $.ui.log(`${PLUGIN}: request_secret failed: ${next.error.kind}`);

    return { result: `${PLUGIN} failed before anything was kept. Nothing was written.` };
  });

  on("ui.render", { component: "Pane", requestId: "secret-pane" }, ($, e, next) =>
    pending === null || e.surface === "mobile" ? next(e) : drawBox($, e, pending),
  );

  on("ui.render", { component: "AbovePrompt" }, ($, e, next) =>
    pending === null || !pending.isInBand || e.surface === "mobile"
      ? next(e)
      : drawBox($, e, pending),
  );

  on("ui.close", (_$, e, next) => {
    // A close before Enter is a cancel; one after it (the person's Escape in the poll's window, or the hook's own) changes nothing.
    if (e.id === PANE && pending !== null && !pending.isInBand && pending.answer === undefined) {
      pending.answer = "";
    }

    return next(e);
  }).catch((_$, e, next) => next(e));

  // The permission is decided on the command as it runs, value in. On a real call the mod restored,
  // an ask is put to the person by the mod, the command as Claude wrote it on show: no dialog and no
  // "always allow" rule carries the value, and in auto mode the classifier never reads it.
  on("tool.check", { tool: "Bash" }, async ($, e, next) => {
    const command = shellCommand(e.input);

    const written =
      e.tool_use_id === undefined || command === null ? undefined : asWritten.get(command);

    if (written === undefined) return next(e);
    const verdict = await next(e);

    if (verdict.decision !== "ask") return verdict;

    const choice = await $.ui
      .ask(`${PLUGIN}: run this command? Each placeholder stands for a kept value.\n${written}`, [
        RUN,
        SKIP,
      ])
      .catch(() => SKIP);

    return choice === RUN
      ? {
          decision: "allow",
          reason: `${PLUGIN}: the person approved the command, its placeholder on show`,
        }
      : { decision: "deny", reason: `${PLUGIN}: the person refused the command` };
  }).catch((_$, e, next) => {
    const command = shellCommand(e.input);

    if (command === null || !asWritten.has(command)) return next(e);

    return {
      decision: "deny",
      reason: `${PLUGIN}: could not put this command to the person, so it is refused`,
    };
  });

  // A placeholder of this session written into a file would stand there as text, where the value was meant.
  on("tool.call", { tool: ["Write", "Edit", "NotebookEdit"] }, (_$, e, next) => {
    const tag = vault.mintedIn(fileText(e));

    return tag === undefined ? next(e) : { deny: writeRefused(tag) };
  }).catch((_$, e, next) =>
    next.called || !fileText(e).includes("[secret-pane:") ? next(e) : { deny: WRITE_UNCHECKED },
  );

  on(
    "tool.call",
    { tool: ["Bash", "Read", "Write", "Edit", "NotebookEdit", "Monitor", "GetTask", "LSP"] },
    async ($, e, next) => {
      let input = e;
      let restoredCommand: string | null = null;

      // An empty vault still reads the command: a placeholder of an earlier session would run as text.
      if (e.tool === "Bash") {
        const restoration = restoreCommand(e.command, vault.valueOf);

        if (restoration.kind === "refused") {
          return {
            deny: `${PLUGIN}: the command was not run: ${restoration.why}${restoration.why.endsWith(".") ? "" : "."}`,
          };
        }

        if (restoration.kind === "restored" && e.run_in_background === true) {
          return {
            deny: `${PLUGIN}: the command was not run: a background command's output is written to disk and read back past the mod. Run it in the foreground.`,
          };
        }

        const unsafe = vault.isEmpty() ? undefined : await changesRefusal($, e.command);

        if (unsafe !== undefined) return { deny: vault.hide(unsafe) };

        if (restoration.kind === "restored") {
          restoredCommand = restoration.command;
          asWritten.set(restoredCommand, e.command);
          input = { ...e, command: restoredCommand };
        }
      }

      if (vault.isEmpty()) return next(input);
      let changed = false;

      const hide = (text: string) => {
        const out = vault.hide(text);

        if (out !== text) changed = true;

        return out;
      };

      try {
        const ran = await next(input);

        if (ran.deny !== undefined) {
          const deny = hide(ran.deny);

          return changed ? { deny } : ran;
        }

        const answer = hidden(ran, hide);

        return changed ? answer : ran;
      } finally {
        if (restoredCommand !== null) asWritten.delete(restoredCommand);
      }
    },
  ).catch((_$, e, next) => {
    const carriesTag = e.tool === "Bash" && e.command.includes("[secret-pane:");

    if (vault.isEmpty() && !carriesTag) return next(e);

    return { deny: next.called ? WITHHELD : NOT_RUN };
  });

  // The net under every door a text reaches the model by: a tool's result, a task's notification,
  // a hook's context, a prompt. Only a row's text blocks and tool_result content may be rewritten.
  on("session.append", (_$, e, next) => {
    if (vault.isEmpty()) return next(e);
    let changed = false;

    const hide = (text: string) => {
      const out = vault.hide(text);

      if (out !== text) changed = true;

      return out;
    };

    const content = hiddenContent(e.message.content, hide);

    return changed ? next({ ...e, message: { ...e.message, content } }) : next(e);
  }).catch((_$, e, next) => {
    if (next.called || vault.isEmpty()) return next(e);

    const content = hiddenContent(e.message.content, () => BLOCK_WITHHELD);

    return next({ ...e, message: { ...e.message, content } });
  });

  on("prompt.submit", ($, e, next) => {
    if (vault.isEmpty()) return next(e);
    const text = vault.hide(e.text);
    const context = e.context?.map((block) => vault.hide(block));

    const contextChanged =
      context !== undefined && context.some((block, at) => block !== e.context?.[at]);

    if (text === e.text && !contextChanged) return next(e);
    $.ui.toast(`${PLUGIN}: hid a kept value from the prompt`);

    return next(context === undefined ? { ...e, text } : { ...e, text, context });
  }).catch((_$, e, next) => {
    if (next.called || vault.isEmpty()) return next(e);

    return { drop: `${PLUGIN}: could not check this prompt for a kept value, so it was not sent.` };
  });
};

files.hooks/scan.ts:
/**
 * Before a git or gh command that may commit or publish, the changes it could
 * carry are read for a kept value: the lines the index and the working tree
 * add, and every untracked file not ignored. The values never leave the mod:
 * git prints the changes, and the mod searches them.
 */

import { type Invocation, invocations, isLocal, parseInvocation, type Program } from "./shell.ts";

/** The shortest line of a value searched for: shorter lines would match ordinary text. */
const MIN_NEEDLE_LENGTH = 8;

/** More untracked files than this and the scan gives up: reading them all would hold the command too long. */
export const MAX_UNTRACKED = 1000;

/** The global options of git that decide which repository and working tree a command acts on. */
const PLACE_OPTIONS = new Set(["-C", "--git-dir", "--work-tree"]);

/** The variables that set the same, as `GIT_DIR=... git commit` writes them. */
const PLACE_VARIABLES = new Map([
  ["GIT_DIR", "--git-dir"],
  ["GIT_WORK_TREE", "--work-tree"],
]);

const DIFF_FLAGS = [
  "-U0",
  "--no-color",
  "--no-ext-diff",
  "--no-textconv",
  "--src-prefix=a/",
  "--dst-prefix=b/",
];

/**
 * Settings every git of the scan runs with, whatever the repository says: no
 * fsmonitor program, file names as they are, a diff of the whole tree from a
 * subdirectory. `-c diff.relative=false` and not `--no-relative`: a git older
 * than the option ignores an unknown setting, where it refuses the flag.
 */
const SETTINGS = [
  "-c",
  "core.fsmonitor=false",
  "-c",
  "core.quotePath=false",
  "-c",
  "diff.relative=false",
];

export type RunResult = {
  readonly exitCode: number;
  readonly stdout: string;
  readonly stderr: string;
  readonly isStdoutTruncated: boolean;
};

/** What a scan needs from the machine; the hooks module builds it from `$`, which cannot cross an import. */
export type Host = {
  /** Runs a command in `cwd`; absent, in the session's working directory, which follows Claude's `cd`. */
  readonly run: (argv: readonly string[], cwd: string | undefined) => Promise<RunResult>;
  /** A file's text, or null for what a read cannot take whole: no regular file, or one over 4 MiB. */
  readonly read: (path: string) => Promise<string | null>;
  /** Whether a path is there, relative to the session's directory or absolute. */
  readonly exists: (path: string) => Promise<boolean>;
};

export type ScanTarget =
  | {
      readonly kind: "place";
      readonly program: Program;
      /** The command as a person names it, `git commit`, `gh pr`. */
      readonly label: string;
      /** Where the command runs, relative to the session's directory or absolute; none, that directory. */
      readonly dir: string | undefined;
      /** The `-C`, `--git-dir` and `--work-tree` the command gives git, handed to every git the scan runs. */
      readonly options: readonly string[];
      /** The files the command is handed to read and send: gh's arguments, git's message file, a file a substitution prints. */
      readonly files: readonly string[];
    }
  | { readonly kind: "unknown"; readonly label: string; readonly spelling: string };

/** Where a kept value was found: a change git holds, a file git would add, a file the command is handed. */
export type Found = {
  readonly path: string;
  readonly where: "tracked" | "untracked" | "handed";
};

export type Scan =
  | { readonly kind: "clean" }
  | { readonly kind: "found"; readonly files: readonly Found[] }
  | { readonly kind: "failed"; readonly why: string };

/** A path as the shell would expand its leading `~`, or nothing where the mod cannot tell what it names. */
function expanded(path: string, home: string | undefined): string | undefined {
  const prefix = /^(?:~|\$HOME|\$\{HOME\})(?=\/|$)/u.exec(path)?.[0];

  if (prefix !== undefined)
    return home === undefined ? undefined : expanded(home + path.slice(prefix.length), undefined);

  if (path === "-" || /[$`]/u.test(path)) return undefined;

  return path.startsWith("~") ? undefined : path;
}

function joined(dir: string | undefined, path: string): string {
  return dir === undefined || path.startsWith("/") ? path : `${dir}/${path}`;
}

/** Each argument of a gh command that may name a file it reads: `@file`, `name=@file` and `--option=file` included. */
function ghPaths(args: readonly string[]): readonly string[] {
  return args.flatMap((arg) => {
    const value = arg.startsWith("--") && arg.includes("=") ? arg.slice(arg.indexOf("=") + 1) : arg;

    const path = value.includes("=@")
      ? value.slice(value.indexOf("=@") + 2)
      : value.replace(/^@/u, "");

    return path === "" || path.startsWith("-") || /\$\(|`/u.test(path) ? [] : [path];
  });
}

/** The file a git command reads its message from: `-F file`, `-Ffile`, `--file file`, `--file=file`; `-` is its standard input. */
function gitPaths(rest: readonly string[]): readonly string[] {
  return rest.flatMap((word, at) => {
    const next = rest[at + 1];

    if ((word === "-F" || word === "--file") && next !== undefined)
      return next === "-" ? [] : [next];

    if (word.startsWith("--file="))
      return word === "--file=-" ? [] : [word.slice("--file=".length)];

    return /^-F[^-]/u.test(word) ? [word.slice(2)] : [];
  });
}

/** The file a command substitution in an argument prints: `"$(cat body.md)"`, `"$(< body.md)"`. */
const SUBSTITUTED_FILE = /\$\(\s*(?:cat\s+|<\s*)((?:'[^']*'|"[^"]*"|[^\s)'"<])+)\s*\)/gu;

function substitutedPaths(args: readonly string[]): readonly string[] {
  return args.flatMap((arg) =>
    [...arg.matchAll(SUBSTITUTED_FILE)].map((match) => (match[1] ?? "").replaceAll(/['"]/gu, "")),
  );
}

function targetOf(
  program: Program,
  { before, args, inputs, cds }: Invocation,
  home: string | undefined,
): ScanTarget {
  const { options, subcommand, rest } = parseInvocation(program, args);
  const label = subcommand === undefined ? program : `${program} ${subcommand}`;
  let dir: string | undefined;

  for (const cd of cds) {
    const path = expanded(cd, home);

    if (path === undefined) return { kind: "unknown", label, spelling: `cd ${cd}` };
    dir = joined(dir, path);
  }

  // The variables git reads for its place, in front of the command, come before the options that override them.
  const assigned = before.flatMap((word) => {
    const [name = "", ...value] = word.split("=");
    const option = PLACE_VARIABLES.get(name);

    return option === undefined || value.length === 0
      ? []
      : [{ name: option, value: value.join("=") }];
  });

  const place: string[] = [];

  for (const { name, value } of program === "git" ? [...assigned, ...options] : []) {
    if (!PLACE_OPTIONS.has(name)) continue;
    const path = value === undefined ? undefined : expanded(value, home);

    if (path === undefined) return { kind: "unknown", label, spelling: `${name} ${value ?? ""}` };
    place.push(name, path);
  }

  const files: string[] = [];
  // git reads a relative file from where its `-C` puts it.
  let base = dir;

  for (let at = 0; at + 1 < place.length; at += 2)
    if (place[at] === "-C") base = joined(base, place[at + 1] ?? "");

  // `gh gist create .env`: the word after gh's subcommand names its action, its words may name files.
  for (const path of program === "gh" ? ghPaths(rest.slice(1)) : []) {
    const resolved = expanded(path, home);

    if (resolved !== undefined) files.push(joined(dir, resolved));
  }

  // These name a file for certain: one the mod cannot tell is a place it cannot check.
  const named = [
    ...(program === "git" ? gitPaths(rest) : []).map((path) => ({ path, from: base })),
    ...substitutedPaths(rest).map((path) => ({ path, from: program === "git" ? base : dir })),
    ...inputs.map((path) => ({ path, from: dir })),
  ];

  for (const { path, from } of named) {
    const resolved = expanded(path, home);

    if (resolved === undefined) return { kind: "unknown", label, spelling: path };

    if (!resolved.startsWith("/dev/")) files.push(joined(from, resolved));
  }

  return { kind: "place", program, label, dir, options: place, files };
}

/**
 * Each place a git or gh command of the command may commit or publish from:
 * a git subcommand outside the local ones, any gh subcommand but gh secret,
 * the first one named for a place. A git or gh with no subcommand prints its
 * help, and one run over ssh runs on another machine: neither gives one.
 */
export function scanTargets(command: string, home: string | undefined): readonly ScanTarget[] {
  const targets = new Map<string, ScanTarget>();

  for (const program of ["git", "gh"] as const) {
    for (const call of invocations(command, program)) {
      if (call.isRemote || isLocal(program, call.args)) continue;
      const target = targetOf(program, call, home);

      const key = JSON.stringify(
        target.kind === "place"
          ? [target.program, target.dir, target.options, target.files]
          : target,
      );

      if (!targets.has(key)) targets.set(key, target);
    }
  }

  return [...targets.values()];
}

/** What the scan looks for: each value's longest line, so a value spread over lines is found in a diff that splits it. */
export function needlesOf(values: readonly string[]): readonly string[] {
  return values.flatMap((value) => {
    const longest = value
      .split(/\r?\n/u)
      .reduce((best, line) => (line.length > best.length ? line : best), "");

    return longest.length >= MIN_NEEDLE_LENGTH ? [longest] : [];
  });
}

/** The path of a `+++` header line, quotes git puts around an unusual name kept off. */
/** The bytes git writes as a letter after a backslash in a quoted file name. */
const NAMED_ESCAPES = new Map([
  ["t", 9],
  ["n", 10],
  ['"', 34],
  ["\\", 92],
]);

/** git's C quoting of an unusual file name undone: `\"`, `\\`, `\t`, `\n` and octal bytes. */
function unquoted(quoted: string): string {
  const bytes: number[] = [];

  for (let at = 0; at < quoted.length; at += 1) {
    const char = quoted[at] ?? "";
    const octal = /^[0-7]{3}/u.exec(quoted.slice(at + 1))?.[0];

    if (char === "\\" && octal !== undefined) {
      bytes.push(Number.parseInt(octal, 8));
      at += octal.length;
    } else if (char === "\\" && NAMED_ESCAPES.has(quoted[at + 1] ?? "")) {
      bytes.push(NAMED_ESCAPES.get(quoted[at + 1] ?? "") ?? 0);
      at += 1;
    } else {
      bytes.push(...new TextEncoder().encode(char));
    }
  }

  return new TextDecoder().decode(new Uint8Array(bytes));
}

/** The path of a `+++` header line: git's quotes undone, and the tab it puts after a name holding a space dropped. */
function headerPath(line: string): string {
  const path = line.slice("+++ ".length).replace(/\t$/u, "");
  const bare = path.startsWith('"') && path.endsWith('"') ? unquoted(path.slice(1, -1)) : path;

  return bare.startsWith("b/") ? bare.slice("b/".length) : bare;
}

/** The files whose added lines hold a needle, read off a `-U0` diff. */
export function addedHits(diff: string, needles: readonly string[]): readonly string[] {
  const hits = new Set<string>();
  let path: string | undefined;
  let isInHunk = false;

  for (const line of diff.split("\n")) {
    if (line.startsWith("diff ")) {
      path = undefined;
      isInHunk = false;
    } else if (!isInHunk && line.startsWith("+++ ")) {
      path = headerPath(line);
    } else if (line.startsWith("@@")) {
      isInHunk = true;
    } else if (
      isInHunk &&
      path !== undefined &&
      line.startsWith("+") &&
      needles.some((needle) => line.includes(needle))
    ) {
      hits.add(path);
    }
  }

  return [...hits];
}

function firstLine(text: string): string {
  return text.trim().split("\n")[0] ?? "";
}

/** git's word for a place that is no repository at all. */
const OUTSIDE = /not a git repository/u;

type Ran =
  | { readonly kind: "ran"; readonly stdout: string }
  | { readonly kind: "failed"; readonly why: string; readonly isOutside: boolean };

type Hits =
  | { readonly kind: "read"; readonly files: readonly Found[] }
  | { readonly kind: "failed"; readonly why: string; readonly isOutside: boolean };

/** The changes of the repository at `target`, read for a needle: the lines the index and the working tree add, the untracked files. */
async function repositoryHits(
  host: Host,
  target: Extract<ScanTarget, { kind: "place" }>,
  needles: readonly string[],
): Promise<Hits> {
  const where = target.dir ?? "the working directory";

  if (target.dir !== undefined) {
    let isThere: boolean;

    try {
      isThere = await host.exists(target.dir);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);

      return {
        kind: "failed",
        why: `${target.dir} could not be looked up: ${message}`,
        isOutside: false,
      };
    }

    if (!isThere) {
      return {
        kind: "failed",
        why: `${target.dir} does not exist yet: run the command that makes it in a Bash call of its own first`,
        isOutside: false,
      };
    }
  }

  const git = async (args: readonly string[]): Promise<Ran> => {
    const shown = `git ${args.join(" ")}`;
    let ran: RunResult;

    // FIXME: a repository's own clean filter (`filter.<driver>.clean` in its .git/config) runs on `git diff`,
    // before the person is asked about the command; git has no setting that turns every filter off.
    try {
      ran = await host.run(["git", ...SETTINGS, ...target.options, ...args], target.dir);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);

      return {
        kind: "failed",
        why: `${shown} did not run in ${where}: ${message}`,
        isOutside: false,
      };
    }

    if (ran.exitCode !== 0) {
      return {
        kind: "failed",
        why: `${shown} exited ${ran.exitCode} in ${where}: ${firstLine(ran.stderr)}`,
        isOutside: OUTSIDE.test(ran.stderr),
      };
    }

    return ran.isStdoutTruncated
      ? {
          kind: "failed",
          why: `${shown} printed more than the 4 MiB the check reads`,
          isOutside: false,
        }
      : { kind: "ran", stdout: ran.stdout };
  };

  const root = await git(["rev-parse", "--show-toplevel"]);

  if (root.kind === "failed") return root;
  const staged = await git(["diff", "--cached", ...DIFF_FLAGS]);

  if (staged.kind === "failed") return staged;
  const unstaged = await git(["diff", ...DIFF_FLAGS]);

  if (unstaged.kind === "failed") return unstaged;

  const listed = await git([
    "ls-files",
    "--others",
    "--exclude-standard",
    "-z",
    "--full-name",
    ":/",
  ]);

  if (listed.kind === "failed") return listed;
  const untracked = listed.stdout.split("\0").filter((path) => path !== "");

  if (untracked.length > MAX_UNTRACKED) {
    return {
      kind: "failed",
      why: `${untracked.length} untracked files, more than the ${MAX_UNTRACKED} the check reads: add what is never committed to .gitignore`,
      isOutside: false,
    };
  }

  const files: Found[] = [
    ...addedHits(staged.stdout, needles),
    ...addedHits(unstaged.stdout, needles),
  ].map((path) => ({ path, where: "tracked" }));

  const top = root.stdout.trim();

  for (const path of untracked) {
    let text: string | null;

    try {
      text = await host.read(`${top}/${path}`);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);

      return { kind: "failed", why: `${path} could not be read: ${message}`, isOutside: false };
    }

    if (text !== null && needles.some((needle) => text.includes(needle)))
      files.push({ path, where: "untracked" });
  }

  return { kind: "read", files };
}

/**
 * What a command at `target` could carry, read for a needle: the files a gh
 * command is handed, and the changes of the repository. Failed whenever the
 * changes could not all be read, but for gh outside any repository, which
 * carries none.
 */
export async function scanChanges(
  host: Host,
  target: Extract<ScanTarget, { kind: "place" }>,
  needles: readonly string[],
): Promise<Scan> {
  if (needles.length === 0) return { kind: "clean" };
  const files = new Map<string, Found>();

  for (const path of target.files) {
    let text: string | null;

    // Most of a gh command's words are no path: one that names nothing is no file gh sends.
    try {
      text = (await host.exists(path)) ? await host.read(path) : null;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);

      return { kind: "failed", why: `${path} could not be read: ${message}` };
    }

    if (text !== null && needles.some((needle) => text.includes(needle)))
      files.set(path, { path, where: "handed" });
  }

  const hits = await repositoryHits(host, target, needles);

  if (hits.kind === "failed" && !(target.program === "gh" && hits.isOutside))
    return { kind: "failed", why: hits.why };

  for (const found of hits.kind === "read" ? hits.files : []) files.set(found.path, found);

  return files.size === 0 ? { kind: "clean" } : { kind: "found", files: [...files.values()] };
}

