/**
 * Where a Bash command may carry a kept value, and the command with each
 * placeholder replaced by it. A value the shell reads as plain text wherever it
 * stands (`isInert`) goes in as it is, anywhere. Any other goes in shell-quoted,
 * as a whole single-quoted word in plain words joined by at most one pipe:
 * anything else the lexer below reads is refused, an allow-list, since no list
 * of what to refuse covers a shell. Either way no git or gh may write the value
 * into history or send it out.
 */

import { isInert, nameOf } from "./vault.ts";

const TAG_WORD = /^'(\[secret-pane:[A-Za-z_][A-Za-z0-9_]*:[0-9a-f]{8}\])'$/u;

const TAG_ANYWHERE = /\[secret-pane:[A-Za-z_][A-Za-z0-9_]*:[0-9a-f]{8}\]/u;

const TAGS = new RegExp(TAG_ANYWHERE.source, "gu");

/**
 * A placeholder right after `$` or `${` (its value would be a variable's
 * name), after `$name` (the value would run into the name) or after `$name:`
 * (a zsh modifier): the brace, the name, the colon, then the placeholder.
 */
const AFTER_DOLLAR = new RegExp(
  String.raw`\$(\{)?(?:([A-Za-z_][A-Za-z0-9_]*)(:)?)?(?=(${TAG_ANYWHERE.source}))`,
  "u",
);

/**
 * The commands a refusal names as its fix, `<placeholder>` and `<NAME>` filled
 * in: each one runs whatever the value holds, which shell.spec.ts holds them to.
 */
export const FIXES = {
  file: "printf '<NAME>=%s\\n' '<placeholder>' >> .env",
  header: "printf 'Authorization: Bearer %s' '<placeholder>' | curl -H @- https://...",
  both: "printf 'Authorization: Bearer %s' '<placeholder>' | curl -H @- -d '<other>' https://...",
  secret: "printf '%s' '<placeholder>' | gh secret set <NAME> --repo org/repo",
  bearer: "curl --oauth2-bearer '<placeholder>' https://api.github.com/...",
  credential:
    "printf 'protocol=https\\nhost=github.com\\nusername=x-access-token\\npassword=%s\\n' '<placeholder>' | git credential approve",
} as const;

/** The fix every refusal of the strict shape ends on. */
const ONE_COMMAND =
  "with this value, a command naming the placeholder is one command or a pipe of two: run the others in a Bash call of their own";

/** Outside quotes, any of these makes the command something other than words and one pipe. */
const OPERATORS_REFUSED = new Set([";", "&", "(", ")", "<", "`", "$", "\n", "\\", "{", "}"]);

/** Programs that run their arguments as another command: a placeholder handed to one is code. */
const WRAPPERS = new Set([
  "sh",
  "bash",
  "zsh",
  "dash",
  "fish",
  "env",
  "xargs",
  "eval",
  "exec",
  "sudo",
  "doas",
  "nohup",
  "time",
  "timeout",
  "nice",
  "watch",
  "command",
  "builtin",
  "ssh",
  "parallel",
  "find",
]);

/**
 * The git subcommands that can neither write a message into history nor send text out. Any other,
 * an alias included, may put a value where it cannot be taken back.
 */
const GIT_LOCAL = new Set([
  "status",
  "diff",
  "log",
  "show",
  "fetch",
  "pull",
  "clone",
  "ls-files",
  "ls-remote",
  "ls-tree",
  "rev-parse",
  "rev-list",
  "blame",
  "grep",
  "describe",
  "shortlog",
  "reflog",
  "cat-file",
  "show-ref",
  "for-each-ref",
  "branch",
  "checkout",
  "switch",
  "restore",
  "reset",
  "add",
  "rm",
  "mv",
  "clean",
  "init",
  "remote",
  "config",
  "worktree",
  "credential",
  "bisect",
  "help",
  "version",
]);

const GIT_PUSH_REFUSED = [
  "`git push` sends commits out, so a command naming a placeholder may not run it:",
  `hand the token to a credential helper that stores it, with ${FIXES.credential}`,
  "(gh's own helper keeps nothing and pushes with gh's login: gh auth status), then push in a command that names no placeholder",
].join(" ");

const GH_REFUSED = [
  "a gh command other than gh secret sends text to GitHub, where it cannot be taken back:",
  `store the value with ${FIXES.secret},`,
  `call the API with ${FIXES.bearer},`,
  "write <NAME> to mention it, or run that gh in a Bash call of its own that names no placeholder",
].join(" ");

const NOT_A_WORD = [
  "the placeholder stands for a value holding characters the shell reads, so it goes in only as a whole single-quoted word, '<placeholder>':",
  `to build a longer text with it, pipe it, as in ${FIXES.header}`,
].join(" ");

const MIXED = [
  "<placeholder> could stand anywhere, but this command also names a value holding characters the shell reads,",
  "which holds every placeholder of the command to the strict shape: write each one as a whole single-quoted word,",
  `as in ${FIXES.both}, or run them in Bash calls of their own`,
].join(" ");

/** git's global options that take the next word as their value. */
const GIT_VALUED_OPTIONS = new Set([
  "-C",
  "-c",
  "--git-dir",
  "--work-tree",
  "--namespace",
  "--exec-path",
  "--config-env",
]);

/** gh's global options that take the next word as their value. */
const GH_VALUED_OPTIONS = new Set(["-R", "--repo"]);

/** The one gh subcommand that takes a value in order to keep it secret. */
const GH_SINK = "secret";

type Word = { readonly raw: string; readonly text: string };

type Lexed =
  | { readonly kind: "words"; readonly commands: readonly (readonly Word[])[] }
  | { readonly kind: "refused"; readonly why: string };

/**
 * Words and pipes, quotes kept in `raw` and removed in `text`. A single-quoted
 * span is literal; a double-quoted one may hold neither `$`, a backtick nor a
 * backslash. Redirections `>`, `>>` and `>&` (`2>&1`) stay words: they run nothing.
 */
function lex(command: string): Lexed {
  const commands: Word[][] = [[]];
  let raw = "";
  let text = "";
  let at = 0;

  const flush = () => {
    if (raw !== "") commands.at(-1)?.push({ raw, text });
    raw = "";
    text = "";
  };

  while (at < command.length) {
    const char = command[at] ?? "";

    if (char === "'") {
      const close = command.indexOf("'", at + 1);

      if (close < 0) return { kind: "refused", why: "an unclosed single quote: close it" };
      raw += command.slice(at, close + 1);
      text += command.slice(at + 1, close);
      at = close + 1;
      continue;
    }

    if (char === '"') {
      const close = command.indexOf('"', at + 1);

      if (close < 0) return { kind: "refused", why: "an unclosed double quote: close it" };
      const inner = command.slice(at + 1, close);

      if (/[$`\\]/u.test(inner)) {
        return {
          kind: "refused",
          why: 'a double-quoted span the shell expands ($, a backtick or a backslash inside "..."): with this value, quote that text with single quotes',
        };
      }

      raw += command.slice(at, close + 1);
      text += inner;
      at = close + 1;
      continue;
    }

    if (char === " " || char === "\t") {
      flush();
      at += 1;
      continue;
    }

    if (char === "|") {
      if (command[at + 1] === "|")
        return { kind: "refused", why: `a list (\`||\`): ${ONE_COMMAND}` };
      flush();

      if (commands.length >= 2)
        return { kind: "refused", why: `more than one pipe: ${ONE_COMMAND}` };
      commands.push([]);
      at += 1;
      continue;
    }

    if (OPERATORS_REFUSED.has(char) && !(char === "&" && raw.endsWith(">"))) {
      return {
        kind: "refused",
        why: `\`${char === "\n" ? "a new line" : char}\` outside quotes: ${ONE_COMMAND}`,
      };
    }

    raw += char;
    text += char;
    at += 1;
  }

  flush();

  if (commands.some((words) => words.length === 0))
    return { kind: "refused", why: `an empty command around a pipe: ${ONE_COMMAND}` };

  return { kind: "words", commands };
}

/**
 * The program a word names, as Windows and macOS find it: its directory, by
 * either slash, and a `.exe` dropped, the case folded (`Git.EXE` runs git).
 */
function basename(word: string): string {
  const name = word
    .slice(Math.max(word.lastIndexOf("/"), word.lastIndexOf("\\")) + 1)
    .toLowerCase();

  return name.endsWith(".exe") ? name.slice(0, -".exe".length) : name;
}

export type Program = "git" | "gh";

export type GlobalOption = { readonly name: string; readonly value: string | undefined };

export type Parsed = {
  readonly options: readonly GlobalOption[];
  readonly subcommand: string | undefined;
  /** The words after the subcommand. */
  readonly rest: readonly string[];
};

/** A git or gh invocation's global options, each value the next word or after `=`, then the first word that is none. */
export function parseInvocation(program: Program, args: readonly string[]): Parsed {
  const valued = program === "git" ? GIT_VALUED_OPTIONS : GH_VALUED_OPTIONS;
  const options: GlobalOption[] = [];

  for (let at = 0; at < args.length; at += 1) {
    const word = args[at] ?? "";
    const equals = word.indexOf("=");

    if (!word.startsWith("-")) return { options, subcommand: word, rest: args.slice(at + 1) };

    if (word.startsWith("--") && equals > 0) {
      options.push({ name: word.slice(0, equals), value: word.slice(equals + 1) });
    } else if (valued.has(word)) {
      options.push({ name: word, value: args[at + 1] });
      at += 1;
    } else {
      options.push({ name: word, value: undefined });
    }
  }

  return { options, subcommand: undefined, rest: [] };
}

/** Whether an invocation can neither write a message into history nor send text out: a local git subcommand, gh secret, or none. */
export function isLocal(program: Program, args: readonly string[]): boolean {
  const { subcommand } = parseInvocation(program, args);

  if (program === "gh") return subcommand === undefined || subcommand === GH_SINK;

  return subcommand === undefined || GIT_LOCAL.has(subcommand);
}

/** Why a git or gh invocation may not run beside a kept value, or nothing. */
function publishRefusal(program: Program, args: readonly string[]): string | undefined {
  if (isLocal(program, args)) return undefined;

  if (program === "gh") return GH_REFUSED;
  const { subcommand } = parseInvocation("git", args);

  return subcommand === "push"
    ? GIT_PUSH_REFUSED
    : `\`git ${subcommand}\` may write the value into history or send it out, where it cannot be taken back (an alias counts as unknown): to mention the secret, write its name, or run that git in a Bash call of its own that names no placeholder`;
}

/** Why one simple command may not carry a value of the strict shape, or nothing; its git and gh are held to the local ones first. */
function programRefusal(words: readonly Word[]): string | undefined {
  const [program = ""] = words.map((word) => word.text);
  const name = basename(program);

  if (/^[A-Za-z_][A-Za-z0-9_]*=/u.test(program)) {
    return "a variable assignment in front of the command: with this value, hand it to the command as an argument or on its standard input";
  }

  return WRAPPERS.has(name)
    ? `\`${name}\` runs its arguments as another command: run that command itself`
    : undefined;
}

/** Outside quotes, each of these ends a simple command. */
const COMMAND_ENDS = new Set([";", "&", "|", "(", ")", "`", "\n"]);

const REDIRECTION = /^(?:&>>|&>|<<<|<<-?|<>|<&|>>|>\||>&|<|>)/u;

/**
 * Where a redirection starting at `at` ends, whether a target word follows
 * it, and whether that target is a file the command reads (`< .env`). No
 * target after a here-string, whose word a command reads, nor after a
 * duplicated descriptor (`2>&1`, `>&-`).
 */
type Redirection = { readonly end: number; readonly hasTarget: boolean; readonly isInput: boolean };

function redirection(command: string, at: number): Redirection {
  const operator = REDIRECTION.exec(command.slice(at))?.[0] ?? ">";
  const end = at + operator.length;

  const descriptor = operator.endsWith("&")
    ? (/^[0-9]*-?/u.exec(command.slice(end))?.[0] ?? "")
    : "";

  if (operator === "<<<" || descriptor !== "")
    return { end: end + descriptor.length, hasTarget: false, isInput: false };

  return { end, hasTarget: command[end] !== "(", isInput: operator === "<" };
}

/** Inside double quotes, the characters a backslash escapes. */
const DOUBLE_QUOTED_ESCAPES = new Set(['"', "\\", "$", "`", "\n"]);

type Part =
  | { readonly kind: "word"; readonly text: string; readonly isQuoted: boolean }
  | { readonly kind: "input"; readonly text: string }
  | { readonly kind: "end"; readonly char: string };

/**
 * The command cut into words and the operators that end a simple command, as
 * the shell would cut it before any expansion: quotes and escapes removed, a
 * comment and a redirection's target dropped. An unclosed quote runs to the end.
 */
function parts(command: string): readonly Part[] {
  const out: Part[] = [];
  let text = "";
  let isWord = false;
  let isQuoted = false;
  let isTargetNext = false;
  let isInputNext = false;
  let at = 0;

  const flush = () => {
    if (isWord && isTargetNext && isInputNext) out.push({ kind: "input", text });
    else if (isWord && !isTargetNext) out.push({ kind: "word", text, isQuoted });

    if (isWord) isTargetNext = false;
    text = "";
    isWord = false;
    isQuoted = false;
  };

  while (at < command.length) {
    const char = command[at] ?? "";

    if (char === "\\") {
      const next = command[at + 1] ?? "";

      // A backslash before a new line joins the two lines.
      if (next !== "\n") {
        text += next;
        isWord = true;
      }

      at += 2;
    } else if (char === "'") {
      const close = command.indexOf("'", at + 1);
      const end = close < 0 ? command.length : close;

      text += command.slice(at + 1, end);
      isWord = true;
      isQuoted = true;
      at = end + 1;
    } else if (char === '"') {
      at += 1;

      while (at < command.length && command[at] !== '"') {
        const inner = command[at] ?? "";
        const next = command[at + 1] ?? "";

        if (inner === "\\" && DOUBLE_QUOTED_ESCAPES.has(next)) {
          text += next === "\n" ? "" : next;
          at += 2;
        } else {
          text += inner;
          at += 1;
        }
      }

      isWord = true;
      isQuoted = true;
      at += 1;
    } else if (char === "#" && !isWord) {
      const newline = command.indexOf("\n", at);

      at = newline < 0 ? command.length : newline;
    } else if (char === " " || char === "\t" || char === "\r") {
      flush();
      at += 1;
    } else if (char === "<" || char === ">" || (char === "&" && command[at + 1] === ">")) {
      // A redirection stays in its command, wherever it stands (`git >/dev/null commit`): the number before it and its target are no words of it.
      if (isWord && !isQuoted && /^\d+$/u.test(text)) {
        text = "";
        isWord = false;
      } else {
        flush();
      }

      const { end, hasTarget, isInput } = redirection(command, at);

      isTargetNext = hasTarget;
      isInputNext = isInput;
      at = end;
    } else if (COMMAND_ENDS.has(char)) {
      flush();
      isTargetNext = false;
      out.push({ kind: "end", char });
      at += 1;
    } else {
      text += char;
      isWord = true;
      at += 1;
    }
  }

  flush();

  return out;
}

export type Invocation = {
  /** Found in the command an `ssh` hands its host: it runs on another machine. */
  readonly isRemote: boolean;
  /** The words before the program's in its simple command: assignments such as `GIT_DIR=...`, a wrapper. */
  readonly before: readonly string[];
  /** The words after the program's, to the end of its simple command. */
  readonly args: readonly string[];
  /** The files its standard input reads: a `<` redirection, or a `cat` piped into it. */
  readonly inputs: readonly string[];
  /** The targets of the `cd` commands before it that still decide where it runs, in order; none, the session's directory. */
  readonly cds: readonly string[];
};

/** The words that may open a simple command and leave the rest of it the command it is. */
const LEADING = new Set(["if", "then", "else", "elif", "do", "while", "until", "!", "{", "time"]);

/**
 * Where a `cd` or `pushd` goes, as written: `~` with no argument, `-` for the
 * directory before, which `popd` goes back to too; nothing for any other command.
 */
function placeChange(texts: readonly string[]): string | undefined {
  const start = texts.findIndex((text) => !LEADING.has(text));
  const [program = "", ...rest] = start < 0 ? [] : texts.slice(start);

  if (program === "popd") return "-";

  if (program !== "cd" && program !== "pushd") return undefined;

  return rest.find((word) => word === "-" || !word.startsWith("-")) ?? "~";
}

function collect(
  command: string,
  program: Program,
  base: readonly string[],
  isRemote: boolean,
  found: Invocation[],
): void {
  const saved: string[][] = [];
  let cds = [...base];
  let words: Extract<Part, { kind: "word" }>[] = [];
  let inputs: string[] = [];
  let piped: readonly string[] = [];
  let isInBackticks = false;

  /** Ends a simple command, and answers the files whose text it prints, for a pipe after it. */
  const end = (): readonly string[] => {
    const texts = words.map((word) => word.text);
    const target = placeChange(texts);
    const first = texts.find((text) => !LEADING.has(text)) ?? "";
    const runsElsewhere = basename(first) === "ssh";
    const read = [...inputs, ...piped];

    if (target !== undefined) cds.push(target);

    for (const [at, word] of words.entries()) {
      if (basename(word.text) === program) {
        found.push({
          isRemote: isRemote || runsElsewhere,
          before: texts.slice(0, at),
          args: texts.slice(at + 1),
          inputs: read,
          cds: [...cds],
        });
      }

      if (word.isQuoted && /[\s;&|()<>`]/u.test(word.text))
        collect(word.text, program, cds, isRemote || runsElsewhere, found);
    }

    const printed =
      basename(first) === "cat"
        ? [
            ...texts.slice(texts.indexOf(first) + 1).filter((text) => !text.startsWith("-")),
            ...read,
          ]
        : [];

    words = [];
    inputs = [];

    return printed;
  };

  for (const part of parts(command)) {
    if (part.kind === "word") {
      words.push(part);
      continue;
    }

    if (part.kind === "input") {
      inputs.push(part.text);
      continue;
    }

    const printed = end();

    piped = part.char === "|" ? printed : [];
    const opens = part.char === "(" || (part.char === "`" && !isInBackticks);
    const closes = part.char === ")" || (part.char === "`" && isInBackticks);

    if (part.char === "`") isInBackticks = !isInBackticks;

    if (opens) {
      saved.push(cds);
      cds = [...cds];
    }

    if (closes) cds = saved.pop() ?? cds;
  }

  end();
}

/**
 * A heredoc whose delimiter is quoted (`<<'EOF'`, `<<"EOF"`, `<<\EOF`), its
 * body text no shell expands; never the `<<` of a here-string's `<<<`.
 */
const LITERAL_HEREDOC =
  /(?<!<)(<<(?!<)(-?)[ \t]*(?:'([^'\n]+)'|"([^"\n]+)"|\\([^\s;&|<>()]+)))[^\n]*\n/gu;

/** The programs that run the text they are handed as commands: a heredoc on their line is a script. */
const RUNNERS = new Set(["sh", "bash", "zsh", "dash", "ksh", "fish", "ssh", "eval", "source", "."]);

/** The runners that are shell builtins, which no prefix can run: `sudo git add .` names no shell. */
const BUILTIN_RUNNERS = new Set(["eval", "source", "."]);

/** The words that may stand before a program and hand it the rest of the command. */
const PREFIXES = new Set([
  "sudo",
  "doas",
  "env",
  "nohup",
  "time",
  "timeout",
  "command",
  "exec",
  "nice",
  "stdbuf",
  "ionice",
]);

/**
 * Whether a simple command of the line runs a heredoc's text: its program,
 * past keywords and assignments, is a shell; or a prefix whose words, an
 * option's value among them (`sudo -u deploy bash`), name one.
 */
function isRunOn(line: string): boolean {
  return line.split(/[;&|()`]|\$\(/u).some((segment) => {
    const words = segment
      .trim()
      .split(/\s+/u)
      .map((word) => basename(word.replaceAll(/["']/gu, "")))
      .filter((word) => !LEADING.has(word) && !/^[A-Za-z_][A-Za-z0-9_]*=/u.test(word));

    const [program = ""] = words;

    return PREFIXES.has(program)
      ? words.some((word) => RUNNERS.has(word) && !BUILTIN_RUNNERS.has(word))
      : RUNNERS.has(program);
  });
}

/**
 * The command with the body of each literal heredoc taken out, the commit
 * message of `git commit -m "$(cat <<'EOF' ... EOF)"` first among them: text
 * that never runs, which would read as commands. A body a shell on the
 * heredoc's own line runs (`bash <<'EOF'`, `cat <<'EOF' | sh`, `ssh host
 * <<'EOF'`) becomes an argument right after its `<<'EOF'`, quoted, so it is read as the
 * command it is, on this machine or another.
 */
function withoutLiteralBodies(command: string): string {
  let out = "";
  let at = 0;

  for (const match of command.matchAll(LITERAL_HEREDOC)) {
    const start = match.index;

    if (start < at) continue;
    const lineStart = command.lastIndexOf("\n", start) + 1;
    const lineEnd = start + match[0].length;
    const isRun = isRunOn(command.slice(lineStart, lineEnd));
    const delimiter = match[3] ?? match[4] ?? match[5] ?? "";
    const stripsTabs = match[2] === "-";
    // The body goes right after its own `<<'EOF'`, in the command the heredoc feeds, before any comment.
    const tokenEnd = start + (match[1]?.length ?? 0);
    let close = lineEnd;
    let isClosed = false;

    const body: string[] = [];

    while (close < command.length) {
      const next = command.indexOf("\n", close);
      const end = next < 0 ? command.length : next;
      const line = command.slice(close, end);

      close = next < 0 ? command.length : next + 1;

      if ((stripsTabs ? line.replace(/^\t+/u, "") : line) === delimiter) {
        isClosed = true;
        break;
      }

      body.push(line);
    }

    out += isRun
      ? `${command.slice(at, tokenEnd)} ${shellQuote(body.join("\n"))}${command.slice(tokenEnd, lineEnd)}`
      : command.slice(at, lineEnd);
    at = isClosed ? close : command.length;
  }

  return out + command.slice(at);
}

/**
 * Each word of the command that names `program`, with the words after it to
 * the end of its simple command and the `cd` targets standing before it. A
 * coarse cut on blanks, quotes and operators, no expansion; a quoted span that
 * holds blanks or operators is read again as a command run from where it
 * stands, so `sh -c "git commit"` names git too, and a literal heredoc's body
 * is no command. A `cd` or `pushd` counts after a keyword or a brace too; a
 * subshell's or a substitution's stays in it.
 */
export function invocations(command: string, program: Program): readonly Invocation[] {
  const found: Invocation[] = [];

  collect(withoutLiteralBodies(command), program, [], false, found);

  return found;
}

/** A value as one single-quoted shell word, whatever it holds. */
export function shellQuote(value: string): string {
  return `'${value.replaceAll("'", `'\\''`)}'`;
}

export type Restoration =
  | { readonly kind: "untouched" }
  | { readonly kind: "restored"; readonly command: string; readonly handed: readonly string[] }
  | { readonly kind: "refused"; readonly why: string };

/** A text with a placeholder's own text and name where it says `<placeholder>` and `<NAME>`: a fix ready to run. */
export function filled(text: string, tag: string): string {
  return text.replaceAll("<placeholder>", tag).replaceAll("<NAME>", nameOf(tag));
}

/** The strict shape: each placeholder a whole single-quoted word, its value shell-quoted, in plain words joined by at most one pipe. */
function restoreStrict(command: string, values: ReadonlyMap<string, string>): Restoration {
  const lexed = lex(command);

  if (lexed.kind === "refused") return { kind: "refused", why: lexed.why };
  const out: string[] = [];

  for (const words of lexed.commands) {
    const restored: string[] = [];

    for (const word of words) {
      const tag = TAG_WORD.exec(word.raw)?.[1];
      const value = tag === undefined ? undefined : values.get(tag);

      if (value !== undefined) {
        restored.push(shellQuote(value));
        continue;
      }

      const stray = TAG_ANYWHERE.exec(word.raw)?.[0];

      if (stray !== undefined) {
        if (!isInert(values.get(stray) ?? ""))
          return { kind: "refused", why: filled(NOT_A_WORD, stray) };
        const other = [...values.keys()].find((key) => !isInert(values.get(key) ?? "")) ?? "";

        return { kind: "refused", why: filled(MIXED, stray).replaceAll("<other>", other) };
      }

      restored.push(word.raw);
    }

    out.push(restored.join(" "));
  }

  // A value piped into a command reaches it too: every command of the pipe is held to the same rule.
  for (const words of lexed.commands) {
    const why = programRefusal(words);

    if (why !== undefined) return { kind: "refused", why };
  }

  return { kind: "restored", command: out.join(" | "), handed: [...new Set(values.values())] };
}

/** Why a placeholder right after a `$` may not stand there, with the fix for its form. */
function afterDollar(command: string): string | undefined {
  const match = AFTER_DOLLAR.exec(command);

  if (match === null) return undefined;
  const [, , name, colon, tag = ""] = match;

  if (name === undefined) {
    return `a placeholder right after \`$\` or \`\${\` would turn its value into a variable's name: write ${tag} alone, with no \`$\`, \`\${\` or \`}\` around it`;
  }

  return colon === undefined
    ? `a placeholder right after \`$${name}\` runs its value into the variable's name: end the name with braces, \`\${${name}}${tag}\``
    : `a placeholder right after \`$${name}:\` makes its value a zsh modifier: end the name with braces, \`\${${name}}:${tag}\``;
}

/**
 * The command with each placeholder put back, or why it may not be. A command
 * that names no placeholder is untouched. `valueOf` answers a kept value, or
 * nothing for a placeholder this session never minted. Once no git or gh word
 * of the whole command may write a value into history or send it out, inert
 * values go in as they are, wherever their placeholder stands; a command
 * holding any other value takes the strict shape.
 */
export function restoreCommand(
  command: string,
  valueOf: (tag: string) => string | undefined,
): Restoration {
  const tags = new Set<string>(command.match(TAGS) ?? []);

  if (tags.size === 0) return { kind: "untouched" };
  const values = new Map<string, string>();

  for (const tag of tags) {
    const value = valueOf(tag);

    if (value === undefined) {
      return {
        kind: "refused",
        why: `${tag} is no placeholder of this session: a new session or a /clear forgot its value, ask for it again with request_secret`,
      };
    }

    values.set(tag, value);
  }

  // With one placeholder, a fix names it; with more, which one it means is not the mod's to guess.
  const [only] = tags.size === 1 ? tags : [];

  for (const program of ["git", "gh"] as const) {
    for (const { args } of invocations(command, program)) {
      const why = publishRefusal(program, args);

      if (why !== undefined)
        return { kind: "refused", why: only === undefined ? why : filled(why, only) };
    }
  }

  if (![...values.values()].every((value) => isInert(value))) return restoreStrict(command, values);
  // The strict shape's lexer refuses every `$` with its own fix; an inert value goes in raw, where a `$` before it acts on it.
  const dollar = afterDollar(command);

  if (dollar !== undefined) return { kind: "refused", why: dollar };
  let restored = command;

  for (const [tag, value] of values) restored = restored.replaceAll(tag, value);

  return { kind: "restored", command: restored, handed: [...new Set(values.values())] };
}

